var JOURNEY_META_TR = {
  umrah: {
    intro: "K\xFC\xE7\xFCk hac: ihram, tavaf, sa\u2018y ve t\u0131ra\u015F olma veya sa\xE7 k\u0131saltma. Y\u0131l\u0131n herhangi bir zaman\u0131nda yap\u0131labilir."
  },
  hajj: {
    intro: "B\xFCy\xFCk hac; Zilhicce\u2019nin 8\u2019inden 13\u2019\xFCne kadar, merkezinde Arafat vakfesi ile."
  }
};
