var JOURNEY_META_UR = {
  umrah: {
    intro: "\u0639\u0645\u0631\u06C1 \u0686\u06BE\u0648\u0679\u0627 \u062D\u062C \u06C1\u06D2: \u0627\u062D\u0631\u0627\u0645\u060C \u0637\u0648\u0627\u0641\u060C \u0633\u0639\u06CC\u060C \u0627\u0648\u0631 \u0633\u0631 \u0645\u0646\u0688\u0648\u0627\u0646\u0627 \u06CC\u0627 \u0628\u0627\u0644 \u06A9\u062A\u0631\u0648\u0627\u0646\u0627\u06D4 \u06CC\u06C1 \u0633\u0627\u0644 \u06A9\u06D2 \u06A9\u0633\u06CC \u0628\u06BE\u06CC \u0648\u0642\u062A \u0627\u062F\u0627 \u06A9\u06CC\u0627 \u062C\u0627 \u0633\u06A9\u062A\u0627 \u06C1\u06D2\u06D4"
  },
  hajj: {
    intro: "\u0628\u0691\u0627 \u062D\u062C\u060C \u0630\u0648 \u0627\u0644\u062D\u062C\u06C1 \u06A9\u06CC 8 \u0633\u06D2 13 \u062A\u0627\u0631\u06CC\u062E \u062A\u06A9\u060C \u062C\u0633 \u06A9\u0627 \u0645\u062D\u0648\u0631 \u0639\u0631\u0641\u0627\u062A \u0645\u06CC\u06BA \u0679\u06BE\u06C1\u0631\u0646\u0627 \u06C1\u06D2\u06D4"
  }
};
var JOURNEY_STEPS_UR = {
  prepare: {
    title: "\u062A\u06CC\u0627\u0631\u06CC \u0627\u0648\u0631 \u0646\u06CC\u062A",
    short: "\u0645\u06CC\u0642\u0627\u062A \u0633\u06D2 \u06AF\u0632\u0631\u0646\u06D2 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u06CC\u06BA",
    detail: "\u0627\u067E\u0646\u06D2 \u0633\u0641\u0631 \u06A9\u06CC \u0633\u0645\u062A \u0648\u0627\u0644\u06D2 \u0645\u06CC\u0642\u0627\u062A \u0633\u06D2 \u06AF\u0632\u0631\u0646\u06D2 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0646\u0627\u062E\u0646 \u0627\u0648\u0631 \u0628\u0627\u0644 \u062A\u0631\u0627\u0634\u06CC\u06BA\u060C \u063A\u0633\u0644 \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u0627\u062D\u0631\u0627\u0645 \u06A9\u06D2 \u06A9\u067E\u0691\u06D2 \u067E\u06C1\u0646\u06CC\u06BA\u06D4 \u067E\u06BE\u0631 \u062F\u0644 \u0645\u06CC\u06BA \u0639\u0645\u0631\u06C1 \u06A9\u06CC \u0646\u06CC\u062A \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u062A\u0644\u0628\u06CC\u06C1 \u0634\u0631\u0648\u0639 \u06A9\u0631\u06CC\u06BA\u06D4 \u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u0646\u06D2 \u06A9\u06D2 \u0628\u0639\u062F \u0628\u0627\u0644 \u0627\u0648\u0631 \u0646\u0627\u062E\u0646 \u0646\u06C1 \u062A\u0631\u0627\u0634\u06CC\u06BA\u060C \u0633\u06CC\u0627 \u06C1\u0648\u0627 \u0644\u0628\u0627\u0633 \u0646\u06C1 \u067E\u06C1\u0646\u06CC\u06BA \u0627\u0648\u0631 \u062E\u0648\u0634\u0628\u0648 \u0646\u06C1 \u0644\u06AF\u0627\u0626\u06CC\u06BA (\u0645\u0631\u062F\u0648\u06BA \u06A9\u06D2 \u0644\u06CC\u06D2)\u060C \u0634\u06A9\u0627\u0631 \u0646\u06C1 \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u0646\u06A9\u0627\u062D \u06A9\u0627 \u0639\u0642\u062F \u0646\u06C1 \u06A9\u0631\u06CC\u06BA \u2014 \u0627\u062D\u0631\u0627\u0645 \u06A9\u0648 \u062A\u0648\u0691\u0646\u06D2 \u0648\u0627\u0644\u06CC \u0686\u06CC\u0632\u0648\u06BA \u0627\u0648\u0631 \u0627\u0633 \u06A9\u06D2 \u06A9\u0641\u0627\u0631\u06D2 \u06A9\u06CC \u062A\u0641\u0635\u06CC\u0644\u0627\u062A \u0645\u0630\u0627\u06C1\u0628\u0650 \u0641\u0642\u06C1 \u0645\u06CC\u06BA \u0645\u062E\u062A\u0644\u0641 \u06C1\u06CC\u06BA\u060C \u0644\u06C1\u0670\u0630\u0627 \u0627\u067E\u0646\u0627 \u0645\u0639\u0627\u0645\u0644\u06C1 \u06A9\u0633\u06CC \u0642\u0627\u0628\u0644\u0650 \u0627\u0639\u062A\u0645\u0627\u062F \u0639\u0627\u0644\u0645 \u0633\u06D2 \u0645\u0639\u0644\u0648\u0645 \u06A9\u0631 \u0644\u06CC\u06BA\u06D4"
  },
  talbiyah: {
    title: "\u062A\u0644\u0628\u06CC\u06C1",
    short: "\u062D\u0631\u0645 \u062A\u06A9 \u067E\u06C1\u0646\u0686\u0646\u06D2 \u062A\u06A9 \u0627\u0633\u06D2 \u062F\u06C1\u0631\u0627\u062A\u06D2 \u0631\u06C1\u06CC\u06BA",
    detail: "\xAB\u0644\u0628\u06CC\u06A9 \u0627\u0644\u0644\u0647\u0645 \u0644\u0628\u06CC\u06A9\u060C \u0644\u0628\u06CC\u06A9 \u0644\u0627 \u0634\u0631\u06CC\u06A9 \u0644\u06A9 \u0644\u0628\u06CC\u06A9\u060C \u0625\u0646 \u0627\u0644\u062D\u0645\u062F \u0648\u0627\u0644\u0646\u0639\u0645\u0629 \u0644\u06A9 \u0648\u0627\u0644\u0645\u0644\u06A9\u060C \u0644\u0627 \u0634\u0631\u06CC\u06A9 \u0644\u06A9\xBB\u06D4 \u0645\u0631\u062F \u0627\u0633\u06D2 \u0628\u0644\u0646\u062F \u0622\u0648\u0627\u0632 \u0633\u06D2 \u06A9\u06C1\u062A\u06D2 \u06C1\u06CC\u06BA \u0627\u0648\u0631 \u062E\u0648\u0627\u062A\u06CC\u0646 \u0622\u06C1\u0633\u062A\u06C1\u06D4 \u0637\u0648\u0627\u0641 \u0634\u0631\u0648\u0639 \u06A9\u0631\u0646\u06D2 \u062A\u06A9 \u0627\u0633\u06D2 \u062C\u0627\u0631\u06CC \u0631\u06A9\u06BE\u06CC\u06BA\u06D4"
  },
  tawaf: {
    title: "\u062E\u0627\u0646\u06C1 \u06A9\u0639\u0628\u06C1 \u06A9\u0627 \u0637\u0648\u0627\u0641",
    short: "\u0633\u0627\u062A \u0686\u06A9\u0631\u060C \u062D\u062C\u0631\u0650 \u0627\u0633\u0648\u062F \u0633\u06D2 \u0634\u0631\u0648\u0639",
    detail: "\u062D\u062C\u0631\u0650 \u0627\u0633\u0648\u062F \u0633\u06D2 \u0634\u0631\u0648\u0639 \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u0646\u06CC\u062A \u0633\u06D2 \u062F\u0627\u062E\u0644 \u06C1\u0648\u06BA \u0627\u0648\u0631 \u06A9\u0639\u0628\u06C1 \u06A9\u0648 \u0627\u067E\u0646\u06CC \u0628\u0627\u0626\u06CC\u06BA \u062C\u0627\u0646\u0628 \u0631\u06A9\u06BE\u062A\u06D2 \u06C1\u0648\u0626\u06D2 \u0633\u0627\u062A \u0686\u06A9\u0631 \u0644\u06AF\u0627\u0626\u06CC\u06BA\u06D4 \u062C\u0628 \u0628\u06BE\u06CC \u062D\u062C\u0631\u0650 \u0627\u0633\u0648\u062F \u06A9\u06D2 \u0633\u0627\u0645\u0646\u06D2 \u0622\u0626\u06CC\u06BA \u062A\u0648 \u0627\u0633\u06D2 \u0686\u06BE\u0648\u0626\u06CC\u06BA \u06CC\u0627 \u0627\u0633 \u06A9\u06CC \u0637\u0631\u0641 \u0627\u0634\u0627\u0631\u06C1 \u06A9\u0631\u06CC\u06BA\u060C \u0627\u0648\u0631 \u062C\u0648 \u0630\u06A9\u0631 \u06CC\u0627 \u0642\u0631\u0622\u0646 \u0622\u0633\u0627\u0646\u06CC \u0633\u06D2 \u06CC\u0627\u062F \u06C1\u0648 \u067E\u0691\u06BE\u06CC\u06BA \u2014 \u06C1\u0631 \u0686\u06A9\u0631 \u06A9\u06D2 \u0644\u06CC\u06D2 \u06A9\u0648\u0626\u06CC \u062E\u0627\u0635 \u062F\u0639\u0627 \u0645\u0642\u0631\u0631 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4 \u0645\u0631\u062F \u067E\u06C1\u0644\u06D2 \u062A\u06CC\u0646 \u0686\u06A9\u0631\u0648\u06BA \u0645\u06CC\u06BA \u062A\u06CC\u0632 \u0686\u0644\u062A\u06D2 \u06C1\u06CC\u06BA (\u0631\u0645\u0644)\u06D4 \u062C\u0628 \u062E\u062A\u0645 \u06A9\u0631 \u0644\u06CC\u06BA \u062A\u0648 \u0627\u06AF\u0631 \u0645\u0645\u06A9\u0646 \u06C1\u0648 \u062A\u0648 \u0645\u0642\u0627\u0645\u0650 \u0627\u0628\u0631\u0627\u06C1\u06CC\u0645 \u06A9\u06D2 \u067E\u06CC\u0686\u06BE\u06D2 \u062F\u0648 \u0631\u06A9\u0639\u062A \u067E\u0691\u06BE\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u0632\u0645\u0632\u0645 \u067E\u0626\u06CC\u06BA\u06D4",
    counterLabel: "\u0686\u06A9\u0631"
  },
  sai: {
    title: "\u0635\u0641\u0627 \u0627\u0648\u0631 \u0645\u0631\u0648\u06C1 \u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u0633\u0639\u06CC",
    short: "\u062F\u0648\u0646\u0648\u06BA \u067E\u06C1\u0627\u0691\u06CC\u0648\u06BA \u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u0633\u0627\u062A \u067E\u06BE\u06CC\u0631\u06D2",
    detail: "\u0635\u0641\u0627 \u0633\u06D2 \u0645\u0631\u0648\u06C1 \u06A9\u06CC \u0637\u0631\u0641 \u062C\u0627\u0626\u06CC\u06BA \u2014 \u06CC\u06C1 \u0627\u06CC\u06A9 \u067E\u06BE\u06CC\u0631\u0627 \u06C1\u06D2 \u2014 \u067E\u06BE\u0631 \u0648\u0627\u067E\u0633 \u0622\u0626\u06CC\u06BA\u060C \u06A9\u0644 \u0633\u0627\u062A \u067E\u06BE\u06CC\u0631\u06D2 \u06C1\u0648\u062A\u06D2 \u06C1\u06CC\u06BA \u0627\u0648\u0631 \u0645\u0631\u0648\u06C1 \u067E\u0631 \u062E\u062A\u0645 \u06C1\u0648\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4 \u0633\u0639\u06CC \u0627\u067E\u0646\u06CC \u062C\u06AF\u06C1 \u0627\u06CC\u06A9 \u0645\u0633\u062A\u0642\u0644 \u0646\u064F\u0633\u06A9 \u06C1\u06D2 \u0627\u0648\u0631 \u0627\u0633\u06D2 \u0645\u062E\u062A\u0635\u0631 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC\u0627 \u062C\u0627\u062A\u0627\u06D4 \u0627\u067E\u0646\u06CC \u0631\u0641\u062A\u0627\u0631 \u0633\u06D2 \u0648\u0642\u0627\u0631 \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0686\u0644\u06CC\u06BA\u060C \u0635\u0631\u0641 \u062F\u0648 \u0633\u0628\u0632 \u0646\u0634\u0627\u0646\u0648\u06BA \u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u062C\u0644\u062F\u06CC \u06A9\u06CC \u062C\u0627\u062A\u06CC \u06C1\u06D2\u06D4",
    counterLabel: "\u067E\u06BE\u06CC\u0631\u0627"
  },
  halq: {
    title: "\u0633\u0631 \u0645\u0646\u0688\u0648\u0627\u0646\u0627 \u06CC\u0627 \u0628\u0627\u0644 \u06A9\u062A\u0631\u0648\u0627\u0646\u0627",
    short: "\u0648\u06C1 \u0645\u0631\u062D\u0644\u06C1 \u062C\u0648 \u0627\u062D\u0631\u0627\u0645 \u0633\u06D2 \u0646\u06A9\u0627\u0644\u062A\u0627 \u06C1\u06D2",
    detail: "\u0645\u0631\u062F \u0633\u0631 \u0645\u0646\u0688\u0648\u0627\u0626\u06CC\u06BA \u06CC\u0627 \u0633\u0631 \u06A9\u06D2 \u062A\u0645\u0627\u0645 \u0628\u0627\u0644 \u06A9\u062A\u0631\u0648\u0627\u0626\u06CC\u06BA\u061B \u0645\u0646\u0688\u0648\u0627\u0646\u0627 \u0627\u0641\u0636\u0644 \u06C1\u06D2\u06D4 \u062E\u0648\u0627\u062A\u06CC\u0646 \u0628\u0627\u0644\u0648\u06BA \u06A9\u06D2 \u0633\u0631\u0648\u06BA \u0633\u06D2 \u0627\u06CC\u06A9 \u067E\u0648\u0631 \u06A9\u06CC \u0645\u0642\u062F\u0627\u0631 \u06A9\u0627\u0679\u06CC\u06BA\u06D4 \u0627\u0633 \u0633\u06D2 \u0639\u0645\u0631\u06C1 \u0645\u06A9\u0645\u0644 \u06C1\u0648 \u062C\u0627\u062A\u06CC \u06C1\u06D2 \u0627\u0648\u0631 \u0627\u062D\u0631\u0627\u0645 \u06A9\u06CC \u062D\u0631\u0627\u0645 \u06A9\u0631\u062F\u06C1 \u06C1\u0631 \u0686\u06CC\u0632 \u062F\u0648\u0628\u0627\u0631\u06C1 \u062D\u0644\u0627\u0644 \u06C1\u0648 \u062C\u0627\u062A\u06CC \u06C1\u06D2\u06D4"
  },
  closing: {
    title: "\u06CC\u0627\u062F \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u0633\u0641\u0631 \u062E\u062A\u0645 \u06A9\u0631\u06CC\u06BA",
    short: "\u062F\u0648 \u0631\u06A9\u0639\u062A \u067E\u0691\u06BE\u06CC\u06BA \u0627\u0648\u0631 \u0634\u06A9\u0631 \u0627\u062F\u0627 \u06A9\u0631\u06CC\u06BA",
    detail: "\u062D\u0631\u0645 \u0645\u06CC\u06BA \u062C\u06C1\u0627\u06BA \u0645\u0645\u06A9\u0646 \u06C1\u0648 \u0646\u0645\u0627\u0632 \u067E\u0691\u06BE\u06CC\u06BA\u060C \u0627\u06AF\u0631 \u0627\u0633\u062A\u0637\u0627\u0639\u062A \u06C1\u0648 \u062A\u0648 \u0635\u062F\u0642\u06C1 \u062F\u06CC\u06BA\u060C \u0627\u0648\u0631 \u0646\u064F\u0633\u06A9 \u0645\u06A9\u0645\u0644 \u06C1\u0648\u0646\u06D2 \u06A9\u06D2 \u0628\u0639\u062F \u06A9\u06CC \u062C\u0627\u0646\u06D2 \u0648\u0627\u0644\u06CC \u062F\u0639\u0627 \u06A9\u0648 \u0646\u06C1 \u0686\u06BE\u0648\u0691\u06CC\u06BA\u06D4 \u0628\u06C1\u062A \u0633\u06D2 \u0644\u0648\u06AF \u0627\u0633 \u06A9\u06D2 \u0628\u0639\u062F \u062A\u0646\u0639\u06CC\u0645 \u0633\u06D2 \u0639\u0645\u0631\u06C1 \u062F\u06C1\u0631\u0627\u062A\u06D2 \u06C1\u06CC\u06BA \u06CC\u0627 \u06A9\u0633\u06CC \u0627\u0648\u0631 \u06A9\u06CC \u0637\u0631\u0641 \u0633\u06D2 \u0627\u062F\u0627 \u06A9\u0631\u062A\u06D2 \u06C1\u06CC\u06BA \u2014 \u06CC\u06C1 \u0622\u067E \u06A9\u06CC \u0627\u067E\u0646\u06CC \u0646\u06CC\u062A \u0627\u0648\u0631 \u0627\u0633\u062A\u0637\u0627\u0639\u062A \u06A9\u0627 \u0645\u0639\u0627\u0645\u0644\u06C1 \u06C1\u06D2\u06D4"
  },
  intention: {
    title: "\u062D\u062C \u06A9\u06CC \u0642\u0633\u0645 \u06A9\u0627 \u0627\u0646\u062A\u062E\u0627\u0628",
    short: "\u062A\u0645\u062A\u0639\u060C \u0642\u0631\u0627\u0646 \u06CC\u0627 \u0627\u0641\u0631\u0627\u062F",
    detail: "\u062A\u0645\u062A\u0639: \u0639\u0645\u0631\u06C1 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u06CC\u06BA\u060C \u0627\u0633\u06D2 \u0645\u06A9\u0645\u0644 \u06A9\u0631\u06CC\u06BA\u060C \u0627\u062D\u0631\u0627\u0645 \u06A9\u06BE\u0648\u0644\u06CC\u06BA\u060C \u067E\u06BE\u0631 8 \u062A\u0627\u0631\u06CC\u062E \u06A9\u0648 \u062D\u062C \u06A9\u06D2 \u0644\u06CC\u06D2 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u06CC\u06BA\u061B \u0627\u0633 \u0645\u06CC\u06BA \u0642\u0631\u0628\u0627\u0646\u06CC \u0644\u0627\u0632\u0645 \u06C1\u06D2\u06D4 \u0642\u0631\u0627\u0646: \u0639\u0645\u0631\u06C1 \u0627\u0648\u0631 \u062D\u062C \u06A9\u0648 \u0627\u06CC\u06A9 \u06C1\u06CC \u0627\u062D\u0631\u0627\u0645 \u0645\u06CC\u06BA \u062C\u0645\u0639 \u06A9\u0631\u06CC\u06BA\u06D4 \u0627\u0641\u0631\u0627\u062F: \u0635\u0631\u0641 \u062D\u062C \u06A9\u06D2 \u0644\u06CC\u06D2 \u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u06CC\u06BA \u0627\u0648\u0631 \u067E\u0648\u0631\u06D2 \u0639\u0631\u0635\u06D2 \u0627\u062D\u0631\u0627\u0645 \u0645\u06CC\u06BA \u0631\u06C1\u06CC\u06BA\u06D4 \u06A9\u0648\u0646 \u0633\u06CC \u0627\u0641\u0636\u0644 \u06C1\u06D2 \u0627\u0648\u0631 \u06C1\u0631 \u0627\u06CC\u06A9 \u0645\u06CC\u06BA \u06A9\u06CC\u0627 \u0644\u0627\u0632\u0645 \u06C1\u06D2\u060C \u06CC\u06C1 \u0622\u067E \u06A9\u06D2 \u062D\u0627\u0644\u0627\u062A \u0627\u0648\u0631 \u0645\u0630\u06C1\u0628 \u067E\u0631 \u0645\u0646\u062D\u0635\u0631 \u06C1\u06D2 \u2014 \u0633\u0641\u0631 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0639\u0644\u0645 \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0641\u06CC\u0635\u0644\u06C1 \u06A9\u0631\u06CC\u06BA\u06D4"
  },
  ihram: {
    title: "\u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u0646\u0627",
    short: "\u063A\u0633\u0644\u060C \u0644\u0628\u0627\u0633\u060C \u0646\u06CC\u062A \u0627\u0648\u0631 \u062A\u0644\u0628\u06CC\u06C1 \u06A9\u0627 \u0622\u063A\u0627\u0632",
    detail: "\u063A\u0633\u0644 \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u0627\u062D\u0631\u0627\u0645 \u06A9\u06D2 \u06A9\u067E\u0691\u06D2 \u067E\u06C1\u0646\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u062C\u0646 \u0645\u0646\u0627\u0633\u06A9 \u06A9\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u06CC\u0627 \u06C1\u06D2 \u0627\u0646 \u06A9\u06CC \u0646\u06CC\u062A \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u062A\u0644\u0628\u06CC\u06C1 \u0634\u0631\u0648\u0639 \u06A9\u0631\u06CC\u06BA\u06D4 \u0627\u0628 \u0627\u062D\u0631\u0627\u0645 \u06A9\u06CC \u067E\u0627\u0628\u0646\u062F\u06CC\u0627\u06BA \u0627\u0633 \u0648\u0642\u062A \u062A\u06A9 \u062C\u0627\u0631\u06CC \u0631\u06C1\u062A\u06CC \u06C1\u06CC\u06BA \u062C\u0628 \u062A\u06A9 \u0622\u067E \u0631\u0645\u06CC \u0646\u06C1 \u06A9\u0631 \u0644\u06CC\u06BA\u060C \u0642\u0631\u0628\u0627\u0646\u06CC \u0646\u06C1 \u062F\u06D2 \u062F\u06CC\u06BA \u0627\u0648\u0631 \u0633\u0631 \u0646\u06C1 \u0645\u0646\u0688\u0648\u0627 \u0644\u06CC\u06BA \u06CC\u0627 \u0628\u0627\u0644 \u0646\u06C1 \u06A9\u062A\u0631\u0648\u0627 \u0644\u06CC\u06BA\u06D4"
  },
  qudum: {
    title: "\u0637\u0648\u0627\u0641\u0650 \u0642\u062F\u0648\u0645 \u0627\u0648\u0631 \u0633\u0639\u06CC",
    short: "\u0637\u0648\u0627\u0641 \u0627\u0644\u0642\u062F\u0648\u0645\u060C \u067E\u06BE\u0631 \u062A\u0645\u062A\u0639 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0633\u0639\u06CC",
    detail: "\u0645\u06A9\u06C1 \u067E\u06C1\u0646\u0686 \u06A9\u0631 \u0633\u0627\u062A \u0686\u06A9\u0631\u0648\u06BA \u06A9\u0627 \u0637\u0648\u0627\u0641\u0650 \u0642\u062F\u0648\u0645 \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u062F\u0648 \u0631\u06A9\u0639\u062A \u067E\u0691\u06BE\u06CC\u06BA\u06D4 \u062A\u0645\u062A\u0639 \u0645\u06CC\u06BA \u0627\u0633 \u06A9\u06D2 \u0628\u0639\u062F \u062D\u062C \u06A9\u06CC \u0633\u0639\u06CC \u06A9\u0631\u06CC\u06BA (\u06CC\u0627 \u0633\u0639\u06CC \u06A9\u0648 \u0637\u0648\u0627\u0641\u0650 \u0627\u0641\u0627\u0636\u06C1 \u06A9\u06D2 \u0628\u0639\u062F \u06A9\u06D2 \u0644\u06CC\u06D2 \u0631\u06A9\u06BE\u06CC\u06BA \u2014 \u0645\u062E\u062A\u0644\u0641 \u0645\u0630\u0627\u06C1\u0628 \u062F\u0648\u0646\u0648\u06BA \u06A9\u0648 \u062F\u0631\u0633\u062A \u0645\u0627\u0646\u062A\u06D2 \u06C1\u06CC\u06BA)\u06D4 \u0627\u0633 \u06A9\u06D2 \u0628\u0639\u062F \u0622\u067E \u0627\u062D\u0631\u0627\u0645 \u0645\u06CC\u06BA \u0631\u06C1\u06CC\u06BA \u06AF\u06D2\u06D4",
    counterLabel: "\u0686\u06A9\u0631"
  },
  tarwiyah: {
    title: "\u0630\u0648 \u0627\u0644\u062D\u062C\u06C1 \u06A9\u06CC 8 \u2014 \u0645\u0646\u06CC\u0670",
    short: "\u06CC\u0648\u0645\u0650 \u062A\u0631\u0648\u06CC\u06C1\u060C \u0645\u0646\u06CC\u0670 \u0645\u06CC\u06BA \u06AF\u0632\u0627\u0631\u0627 \u062C\u0627\u062A\u0627 \u06C1\u06D2",
    detail: "\u0627\u06AF\u0631 \u0622\u067E \u0646\u06D2 \u0627\u062D\u0631\u0627\u0645 \u06A9\u06BE\u0648\u0644 \u0644\u06CC\u0627 \u06C1\u06D2 \u062A\u0648 \u062D\u062C \u06A9\u06D2 \u0644\u06CC\u06D2 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0627\u062D\u0631\u0627\u0645 \u0628\u0627\u0646\u062F\u06BE\u06CC\u06BA \u0627\u0648\u0631 \u0645\u0646\u06CC\u0670 \u062C\u0627\u0626\u06CC\u06BA\u060C \u0627\u0648\u0631 \u0638\u06C1\u0631\u060C \u0639\u0635\u0631\u060C \u0645\u063A\u0631\u0628\u060C \u0639\u0634\u0627\u0621 \u0627\u0648\u0631 \u0641\u062C\u0631 \u06A9\u06CC \u0646\u0645\u0627\u0632\u06CC\u06BA \u0648\u06C1\u0627\u06BA \u067E\u0691\u06BE\u06CC\u06BA\u061B \u06C1\u0631 \u0627\u06CC\u06A9 \u062F\u0648 \u0631\u06A9\u0639\u062A \u0642\u0635\u0631\u060C \u0645\u06AF\u0631 \u0628\u063A\u06CC\u0631 \u062C\u0645\u0639 \u06A9\u06D2\u06D4 \u0639\u0631\u0641\u0627\u062A \u062C\u0627\u0646\u06D2 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0631\u0627\u062A \u0645\u0646\u06CC\u0670 \u0645\u06CC\u06BA \u06AF\u0632\u0627\u0631\u06CC\u06BA\u06D4"
  },
  arafah: {
    title: "\u0630\u0648 \u0627\u0644\u062D\u062C\u06C1 \u06A9\u06CC 9 \u2014 \u0639\u0631\u0641\u0627\u062A",
    short: "\u0648\u06C1 \u0679\u06BE\u06C1\u0631\u0646\u0627 \u062C\u0648 \u062D\u062C \u06C1\u06D2",
    detail: "\u0633\u0648\u0631\u062C \u0646\u06A9\u0644\u0646\u06D2 \u06A9\u06D2 \u0628\u0639\u062F \u0639\u0631\u0641\u0627\u062A \u062C\u0627\u0626\u06CC\u06BA \u0627\u0648\u0631 \u062F\u0648\u067E\u06C1\u0631 \u0633\u06D2 \u063A\u0631\u0648\u0628 \u062A\u06A9 \u0648\u06C1\u0627\u06BA \u0679\u06BE\u06C1\u0631\u06CC\u06BA\u060C \u0627\u0648\u0631 \u0638\u06C1\u0631 \u0627\u0648\u0631 \u0639\u0635\u0631 \u06A9\u06CC \u0646\u0645\u0627\u0632\u06CC\u06BA \u062C\u0645\u0639 \u0627\u0648\u0631 \u0642\u0635\u0631 \u06A9\u0631 \u06A9\u06D2 \u067E\u0691\u06BE\u06CC\u06BA\u06D4 \u067E\u0648\u0631\u0627 \u0639\u0631\u0641\u0627\u062A \u0679\u06BE\u06C1\u0631\u0646\u06D2 \u06A9\u06CC \u062C\u06AF\u06C1 \u06C1\u06D2\u060C \u0627\u06AF\u0631\u0686\u06C1 \u0644\u0648\u06AF \u062C\u0628\u0644 \u0627\u0644\u0631\u062D\u0645\u06C1 \u06A9\u06CC \u0686\u0679\u0627\u0646 \u06A9\u06D2 \u067E\u0627\u0633 \u062C\u0645\u0639 \u06C1\u0648\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4 \u0627\u0633 \u062F\u0646 \u06A9\u0648 \u062A\u0644\u0628\u06CC\u06C1\u060C \u0630\u06A9\u0631\u060C \u0642\u0631\u0622\u0646\u060C \u062A\u0648\u0628\u06C1 \u0627\u0648\u0631 \u062F\u0639\u0627 \u0633\u06D2 \u0628\u06BE\u0631\u06CC\u06BA \u2014 \u06CC\u06C1\u06CC \u0648\u06C1 \u062F\u0646 \u06C1\u06D2 \u062C\u0633 \u067E\u0631 \u062D\u062C \u06A9\u0627 \u062F\u0627\u0631\u0648\u0645\u062F\u0627\u0631 \u06C1\u06D2\u06D4"
  },
  muzdalifah: {
    title: "\u0645\u0632\u062F\u0644\u0641\u06C1 \u06A9\u06CC \u0631\u0627\u062A",
    short: "\u063A\u0631\u0648\u0628 \u06A9\u06D2 \u0628\u0639\u062F \u0646\u06A9\u0644\u06CC\u06BA\u060C \u0646\u0645\u0627\u0632 \u067E\u0691\u06BE\u06CC\u06BA \u0627\u0648\u0631 \u06A9\u0646\u06A9\u0631\u06CC\u0627\u06BA \u062C\u0645\u0639 \u06A9\u0631\u06CC\u06BA",
    detail: "\u063A\u0631\u0648\u0628 \u06A9\u06D2 \u0628\u0639\u062F \u2014 \u0627\u0648\u0631 \u0635\u0628\u062D \u06A9\u06CC \u067E\u0648 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u2014 \u0639\u0631\u0641\u0627\u062A \u0633\u06D2 \u0646\u06A9\u0644\u06CC\u06BA \u0627\u0648\u0631 \u0645\u0632\u062F\u0644\u0641\u06C1 \u062C\u0627\u0626\u06CC\u06BA\u060C \u062C\u06C1\u0627\u06BA \u0645\u063A\u0631\u0628 \u0627\u0648\u0631 \u0639\u0634\u0627\u0621 \u0627\u06A9\u0679\u06BE\u06CC \u067E\u0691\u06BE\u06CC\u06BA \u0627\u0648\u0631 \u0631\u0627\u062A \u06AF\u0632\u0627\u0631\u06CC\u06BA\u06D4 \u0631\u0645\u06CC \u06A9\u06CC \u06A9\u0646\u06A9\u0631\u06CC\u0627\u06BA \u06CC\u06C1\u06CC\u06BA \u0633\u06D2 \u062C\u0645\u0639 \u06A9\u0631\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u067E\u0648 \u067E\u06BE\u0679\u0646\u06D2 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u06CC\u0627 \u0627\u0633 \u06A9\u06D2 \u0642\u0631\u06CC\u0628 \u0645\u0646\u06CC\u0670 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0646\u06A9\u0644\u06CC\u06BA\u06D4"
  },
  aqaba: {
    title: "10 \u2014 \u0628\u0691\u06D2 \u062C\u0645\u0631\u06D2 \u06A9\u06CC \u0631\u0645\u06CC",
    short: "\u062C\u0645\u0631\u0629 \u0627\u0644\u0639\u0642\u0628\u06C1 \u067E\u0631 \u0633\u0627\u062A \u06A9\u0646\u06A9\u0631\u06CC\u0627\u06BA",
    detail: "\u0645\u0646\u06CC\u0670 \u0645\u06CC\u06BA \u0628\u0691\u06D2 \u062C\u0645\u0631\u06D2 (\u0639\u0642\u0628\u06C1\u060C \u062C\u0648 \u0645\u06A9\u06C1 \u0633\u06D2 \u0642\u0631\u06CC\u0628 \u062A\u0631 \u06C1\u06D2) \u06A9\u0648 \u0633\u0627\u062A \u06A9\u0646\u06A9\u0631\u06CC\u0648\u06BA \u0633\u06D2 \u0631\u0645\u06CC \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u06C1\u0631 \u067E\u06BE\u06CC\u0646\u06A9\u0646\u06D2 \u067E\u0631 \xAB\u0627\u0644\u0644\u06C1 \u0627\u06A9\u0628\u0631\xBB \u06A9\u06C1\u06CC\u06BA\u06D4 \u0627\u0633\u06CC \u0631\u0645\u06CC \u0633\u06D2 \u0627\u062D\u0631\u0627\u0645 \u0633\u06D2 \u0628\u0691\u06CC \u0631\u062E\u0635\u062A \u062D\u0627\u0635\u0644 \u06C1\u0648\u062A\u06CC \u06C1\u06D2\u06D4",
    counterLabel: "\u06A9\u0646\u06A9\u0631\u06CC"
  },
  hady: {
    title: "10 \u2014 \u0642\u0631\u0628\u0627\u0646\u06CC \u0627\u0648\u0631 \u0633\u0631 \u0645\u0646\u0688\u0648\u0627\u0646\u0627",
    short: "\u06C1\u062F\u06CC\u060C \u067E\u06BE\u0631 \u0645\u0646\u0688\u0648\u0627\u0646\u0627 \u06CC\u0627 \u06A9\u062A\u0631\u0648\u0627\u0646\u0627",
    detail: "\u062A\u0645\u062A\u0639 \u0627\u0648\u0631 \u0642\u0631\u0627\u0646 \u0645\u06CC\u06BA \u062C\u0648 \u0642\u0631\u0628\u0627\u0646\u06CC \u0644\u0627\u0632\u0645 \u06C1\u06D2 \u0648\u06C1 \u0627\u062F\u0627 \u06A9\u0631\u06CC\u06BA \u2014 \u0622\u062C \u06A9\u0644 \u0627\u06A9\u062B\u0631 \u062D\u0627\u062C\u06CC \u06A9\u0648\u0626\u06CC \u0645\u062C\u0627\u0632 \u0646\u0645\u0627\u0626\u0646\u062F\u06C1 \u0645\u0642\u0631\u0631 \u06A9\u0631\u062A\u06D2 \u06C1\u06CC\u06BA\u060C \u062C\u0648 \u0642\u0628\u0648\u0644 \u06A9\u06CC\u0627 \u062C\u0627\u062A\u0627 \u06C1\u06D2\u06D4 \u067E\u06BE\u0631 \u0633\u0631 \u0645\u0646\u0688\u0648\u0627\u0626\u06CC\u06BA \u06CC\u0627 \u0628\u0627\u0644 \u06A9\u062A\u0631\u0648\u0627\u0626\u06CC\u06BA\u061B \u062E\u0648\u0627\u062A\u06CC\u0646 \u0627\u06CC\u06A9 \u067E\u0648\u0631 \u06A9\u06CC \u0645\u0642\u062F\u0627\u0631 \u06A9\u0627\u0679\u06CC\u06BA\u06D4 \u0631\u0645\u06CC\u060C \u0642\u0631\u0628\u0627\u0646\u06CC \u0627\u0648\u0631 \u0645\u0646\u0688\u0648\u0627\u0646\u06D2 \u0633\u06D2 \u0627\u062D\u0631\u0627\u0645 \u06A9\u06CC \u062D\u0631\u0627\u0645 \u06A9\u0631\u062F\u06C1 \u06C1\u0631 \u0686\u06CC\u0632 \u062D\u0644\u0627\u0644 \u06C1\u0648 \u062C\u0627\u062A\u06CC \u06C1\u06D2\u060C \u0633\u0648\u0627\u0626\u06D2 \u0628\u06CC\u0648\u06CC \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0645\u0628\u0627\u0634\u0631\u062A \u06A9\u06D2\u06D4"
  },
  ifadah: {
    title: "10 \u0633\u06D2 12 \u2014 \u0637\u0648\u0627\u0641\u0650 \u0627\u0641\u0627\u0636\u06C1",
    short: "\u062D\u062C \u06A9\u0627 \u0631\u06A9\u0646\u060C \u0627\u0648\u0631 \u0633\u0639\u06CC \u0627\u06AF\u0631 \u0627\u0628\u06BE\u06CC \u0628\u0627\u0642\u06CC \u06C1\u06D2",
    detail: "\u0637\u0648\u0627\u0641\u0650 \u0627\u0641\u0627\u0636\u06C1 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0645\u06A9\u06C1 \u0648\u0627\u067E\u0633 \u062C\u0627\u0626\u06CC\u06BA\u060C \u0633\u0627\u062A \u0686\u06A9\u0631\u060C \u0627\u0648\u0631 \u0627\u06AF\u0631 \u0622\u067E \u0646\u06D2 \u062D\u062C \u06A9\u06CC \u0633\u0639\u06CC \u067E\u06C1\u0644\u06D2 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC \u062A\u0648 \u0627\u0633 \u06A9\u06D2 \u0628\u0639\u062F \u0633\u0639\u06CC \u06A9\u0631\u06CC\u06BA\u06D4 \u06CC\u06C1 \u0637\u0648\u0627\u0641 \u0628\u0646\u06CC\u0627\u062F\u06CC \u0631\u06A9\u0646 \u06C1\u06D2: \u062D\u062C \u0627\u0633 \u06A9\u06D2 \u0628\u063A\u06CC\u0631 \u0645\u06A9\u0645\u0644 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u062A\u0627\u06D4",
    counterLabel: "\u0686\u06A9\u0631"
  },
  tashreeq: {
    title: "11 \u0633\u06D2 13 \u2014 \u0627\u06CC\u0627\u0645\u0650 \u062A\u0634\u0631\u06CC\u0642",
    short: "\u06C1\u0631 \u062F\u0648\u067E\u06C1\u0631 \u0628\u0639\u062F \u062A\u06CC\u0646 \u062C\u0645\u0631\u06D2\u060C \u067E\u06BE\u0631 \u0645\u0646\u06CC\u0670",
    detail: "\u0632\u0648\u0627\u0644 \u06A9\u06D2 \u0628\u0639\u062F \u06C1\u0631 \u062F\u0648\u067E\u06C1\u0631 \u062A\u06CC\u0646 \u062C\u0645\u0631\u0624\u06BA \u06A9\u0648 \u062A\u0631\u062A\u06CC\u0628 \u0633\u06D2 \u2014 \u067E\u06C1\u0644\u06D2 \u0686\u06BE\u0648\u0679\u0627\u060C \u067E\u06BE\u0631 \u062F\u0631\u0645\u06CC\u0627\u0646\u06C1\u060C \u067E\u06BE\u0631 \u0628\u0691\u0627 \u2014 \u06C1\u0631 \u0627\u06CC\u06A9 \u06A9\u0648 \u0633\u0627\u062A \u06A9\u0646\u06A9\u0631\u06CC\u0648\u06BA \u0633\u06D2 \u0631\u0645\u06CC \u06A9\u0631\u06CC\u06BA \u0627\u0648\u0631 \u06C1\u0631 \u067E\u06BE\u06CC\u0646\u06A9\u0646\u06D2 \u067E\u0631 \xAB\u0627\u0644\u0644\u06C1 \u0627\u06A9\u0628\u0631\xBB \u06A9\u06C1\u06CC\u06BA\u06D4 \u06CC\u06C1 \u0631\u0627\u062A\u06CC\u06BA \u0645\u0646\u06CC\u0670 \u0645\u06CC\u06BA \u06AF\u0632\u0627\u0631\u06CC\u06BA\u06D4 \u062C\u0633 \u0646\u06D2 12 \u062A\u0627\u0631\u06CC\u062E \u06A9\u0648 \u0627\u0633 \u062F\u0646 \u06A9\u06CC \u0631\u0645\u06CC \u06A9\u0631 \u06A9\u06D2 \u0648\u0627\u067E\u0633\u06CC \u06A9\u06CC\u060C \u0627\u0633 \u067E\u0631 \u06A9\u0648\u0626\u06CC \u06AF\u0646\u0627\u06C1 \u0646\u06C1\u06CC\u06BA\u061B \u0627\u0648\u0631 \u062C\u0648 13 \u062A\u06A9 \u0679\u06BE\u06C1\u0631\u0627\u060C \u0627\u0633 \u067E\u0631 \u0628\u06BE\u06CC \u06A9\u0648\u0626\u06CC \u06AF\u0646\u0627\u06C1 \u0646\u06C1\u06CC\u06BA\u06D4",
    counterLabel: "\u06A9\u0646\u06A9\u0631\u06CC"
  },
  wada: {
    title: "\u0637\u0648\u0627\u0641\u0650 \u0648\u062F\u0627\u0639",
    short: "\u0645\u06A9\u06C1 \u0633\u06D2 \u0646\u06A9\u0644\u0646\u06D2 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0637\u0648\u0627\u0641 \u0627\u0644\u0648\u062F\u0627\u0639",
    detail: "\u0648\u0637\u0646 \u0648\u0627\u067E\u0633\u06CC \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0637\u0648\u0627\u0641\u0650 \u0648\u062F\u0627\u0639 \u06A9\u06D2 \u0637\u0648\u0631 \u067E\u0631 \u0633\u0627\u062A \u0686\u06A9\u0631 \u0644\u06AF\u0627\u0626\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u062F\u0648 \u0631\u06A9\u0639\u062A \u067E\u0691\u06BE\u06CC\u06BA \u0627\u0648\u0631 \u0631\u0648\u0627\u0646\u06C1 \u06C1\u0648\u06BA\u06D4 \u0645\u06A9\u06C1 \u0633\u06D2 \u0646\u06A9\u0644\u0646\u06D2 \u0648\u0627\u0644\u06D2 \u06C1\u0631 \u0634\u062E\u0635 \u06A9\u06D2 \u0644\u06CC\u06D2 \u06CC\u06C1 \u062D\u062C \u06A9\u0627 \u0622\u062E\u0631\u06CC \u0646\u064F\u0633\u06A9 \u06C1\u06D2\u06D4",
    counterLabel: "\u0686\u06A9\u0631"
  }
};

// src/content/journeyId.ts
var JOURNEY_META_ID = {
  umrah: {
    intro: "Umrah, ibadah haji kecil: ihram, tawaf, sa\u2019i, lalu mencukur atau memotong rambut. Dapat dikerjakan kapan saja sepanjang tahun."
  },
  hajj: {
    intro: "Haji, ibadah haji besar, pada tanggal 8 sampai 13 Zulhijah, dengan wukuf di Arafah sebagai pusatnya."
  }
};
var JOURNEY_STEPS_ID = {
  prepare: {
    title: "Bersiap dan berniat",
    short: "Kenakan ihram sebelum melewati miqat",
    detail: "Potong kuku dan rambut, mandi, lalu kenakan pakaian ihram sebelum melewati miqat yang sesuai arah perjalanan Anda. Kemudian niatkan umrah di dalam hati dan mulailah talbiyah. Setelah berihram, jangan memotong rambut atau kuku, memakai pakaian berjahit atau wewangian (bagi laki-laki), berburu, atau melangsungkan akad nikah \u2014 perincian tentang apa yang membatalkan ihram dan apa kafaratnya berbeda antarmazhab, jadi pastikan keadaan Anda sendiri dengan ulama yang Anda percaya."
  },
  talbiyah: {
    title: "Talbiyah",
    short: "Terus ulangi sampai Anda tiba di tanah haram",
    detail: "\xABLabbayka All\u0101humma labbayk, labbayka l\u0101 shar\u012Bka laka labbayk, inna al-\u1E25amda wa an-ni\u2018mata laka wa al-mulk, l\u0101 shar\u012Bka lak.\xBB Laki-laki mengucapkannya dengan suara keras; perempuan mengucapkannya pelan. Teruskan sampai Anda memulai tawaf."
  },
  tawaf: {
    title: "Tawaf mengelilingi Kabah",
    short: "Tujuh putaran, dimulai dari Hajar Aswad",
    detail: "Masuklah dari Hajar Aswad dengan niat memulai, lalu kelilingi Kabah tujuh kali dengan Kabah berada di sebelah kiri Anda. Sentuh atau isyaratkan ke Hajar Aswad setiap kali melewatinya, dan bacalah dzikir atau Al-Quran yang mudah bagi Anda \u2014 tidak ada doa tertentu yang ditetapkan untuk setiap putaran. Laki-laki berjalan cepat pada tiga putaran pertama. Setelah selesai, salat dua rakaat di belakang Maqam Ibrahim bila memungkinkan, lalu minumlah air zamzam.",
    counterLabel: "putaran"
  },
  sai: {
    title: "Sa\u2019i antara Safa dan Marwah",
    short: "Tujuh kali bolak-balik antara dua bukit itu",
    detail: "Berjalanlah dari Safa ke Marwah \u2014 itu satu kali \u2014 lalu kembali, tujuh kali seluruhnya, dan berakhir di Marwah. Sa\u2019i adalah manasik yang berdiri sendiri dan tidak diringkas. Berjalanlah sesuai kemampuan Anda; hanya bagian di antara dua tanda hijau yang dilakukan dengan berlari kecil.",
    counterLabel: "kali"
  },
  halq: {
    title: "Mencukur atau memotong rambut",
    short: "Langkah yang melepaskan Anda dari ihram",
    detail: "Laki-laki mencukur gundul atau memotong rambut secara merata; mencukur gundul lebih utama. Perempuan memotong sepanjang ujung jari dari ujung rambut. Dengan ini umrah pun selesai dan segala yang dilarang ihram kembali halal bagi Anda."
  },
  closing: {
    title: "Berdzikir, dan tutup perjalanan ini",
    short: "Salat dua rakaat dan bersyukur",
    detail: "Salatlah di mana pun memungkinkan di tanah haram, bersedekah bila Anda mampu, dan jaga doa yang dipanjatkan setelah sebuah manasik selesai. Banyak orang kemudian mengulang umrah dari Tan\u2019im atau mengerjakannya lagi untuk orang lain \u2014 itu terserah niat dan kemampuan Anda sendiri."
  },
  intention: {
    title: "Pilih jenis haji Anda",
    short: "Tamatu\u2019, Qiran, atau Ifrad",
    detail: "Tamatu\u2019: berihram untuk umrah, selesaikan, lepaskan ihram, lalu berihram lagi untuk haji pada tanggal 8; jenis ini membawa kewajiban hewan kurban. Qiran: menggabung umrah dan haji dalam satu ihram. Ifrad: berihram untuk haji saja dan tetap berihram sampai selesai. Mana yang lebih utama, dan apa yang diwajibkan masing-masing, bergantung pada keadaan dan mazhab Anda \u2014 putuskan dengan ilmu sebelum Anda berangkat."
  },
  ihram: {
    title: "Masuk ihram",
    short: "Mandi, berpakaian, berniat, dan mulailah talbiyah",
    detail: "Mandilah dan kenakan pakaian ihram, lalu niatkan manasik yang Anda pilih dan mulailah talbiyah. Larangan-larangan ihram sekarang berlaku sampai Anda melempar jumrah, berkurban, dan mencukur atau memotong rambut."
  },
  qudum: {
    title: "Tawaf qudum dan sa\u2019i",
    short: "Tawaf al-Qudum, lalu sa\u2019i bagi yang Tamatu\u2019",
    detail: "Setibanya di Makkah, kerjakan tawaf qudum tujuh putaran lalu salat dua rakaat. Bagi Tamatu\u2019, lanjutkan dengan sa\u2019i haji (atau tunda sa\u2019i sampai setelah tawaf ifadah \u2014 keduanya dipandang sah oleh mazhab yang berbeda). Anda kemudian tetap berihram.",
    counterLabel: "putaran"
  },
  tarwiyah: {
    title: "8 Zulhijah \u2014 Mina",
    short: "Hari Tarwiyah, dihabiskan di Mina",
    detail: "Berihramlah untuk haji jika sebelumnya Anda telah melepaskannya, lalu berangkat ke Mina, salat Zuhur, Asar, Magrib, Isya, dan Subuh di sana, masing-masing diringkas menjadi dua rakaat tetapi tidak dijamak. Habiskan malam di Mina sebelum berangkat ke Arafah."
  },
  arafah: {
    title: "9 Zulhijah \u2014 Arafah",
    short: "Wukuf yang menjadi inti haji",
    detail: "Setelah matahari terbit, berangkatlah ke Arafah dan berwukuf di sana dari siang sampai matahari terbenam, dengan salat Zuhur dan Asar dijamak dan diringkas. Seluruh Arafah adalah tempat wukuf, meski batu di Jabal ar-Rahmah menjadi tempat orang berkumpul. Penuhilah hari itu dengan talbiyah, dzikir, Al-Quran, taubat, dan doa \u2014 pada hari inilah haji itu bergantung."
  },
  muzdalifah: {
    title: "Malam di Muzdalifah",
    short: "Berangkat setelah matahari terbenam, salat, dan kumpulkan kerikil",
    detail: "Tinggalkan Arafah setelah matahari terbenam \u2014 sebelum fajar \u2014 lalu pergi ke Muzdalifah, tempat Anda salat Magrib dan Isya dijamak dan menghabiskan malam. Kumpulkan kerikil untuk melempar di sini, lalu berangkat ke Mina sebelum atau sekitar fajar."
  },
  aqaba: {
    title: "10 Zulhijah \u2014 Melempar jumrah besar",
    short: "Tujuh kerikil di Jumrat al-Aqabah",
    detail: "Di Mina, lemparkan tujuh kerikil ke jumrah besar (al-Aqabah, yang paling dekat dengan Makkah) sambil mengucapkan \xABAll\u0101hu akbar\xBB pada setiap lemparan. Dengan lemparan ini berlakulah tahallul besar dari ihram.",
    counterLabel: "kerikil"
  },
  hady: {
    title: "10 Zulhijah \u2014 Berkurban dan mencukur",
    short: "Hewan kurban, lalu mencukur atau memotong",
    detail: "Sembelih hewan kurban yang diwajibkan bagi Tamatu\u2019 dan Qiran \u2014 dewasa ini kebanyakan jamaah menunjuk wakil yang resmi, dan itu diterima. Kemudian cukurlah gundul atau potong rambut; perempuan memotong sepanjang ujung jari. Dengan selesainya melempar, berkurban, dan mencukur, segala yang dilarang ihram menjadi halal kembali kecuali hubungan dengan istri."
  },
  ifadah: {
    title: "10 sampai 12 Zulhijah \u2014 Tawaf ifadah",
    short: "Rukun haji, dan sa\u2019i bila masih terhutang",
    detail: "Kembalilah ke Makkah untuk tawaf ifadah, tujuh putaran, diikuti sa\u2019i jika Anda belum mengerjakannya untuk haji ini. Tawaf inilah rukun yang menentukan: haji tidak sah tanpanya.",
    counterLabel: "putaran"
  },
  tashreeq: {
    title: "11 sampai 13 Zulhijah \u2014 hari-hari Tasyrik",
    short: "Tiga jumrah setiap siang, lalu kembali ke Mina",
    detail: "Setiap siang setelah zawal, lemparkan ketiga jumrah secara berurutan \u2014 yang kecil, lalu yang tengah, lalu yang besar \u2014 masing-masing tujuh kerikil, sambil mengucapkan \xABAll\u0101hu akbar\xBB pada setiap lemparan. Habiskan malam-malam ini di Mina. Siapa yang berangkat setelah tanggal 12, setelah melempar pada hari itu, ia melakukannya tanpa dosa; dan siapa yang tinggal sampai tanggal 13, ia pun melakukannya tanpa dosa.",
    counterLabel: "kerikil"
  },
  wada: {
    title: "Tawaf wada",
    short: "Tawaf al-Wada\u2019 sebelum meninggalkan Makkah",
    detail: "Sebelum pulang, kerjakan tujuh putaran sebagai tawaf wada, lalu salat dua rakaat dan berangkat. Inilah manasik terakhir haji bagi siapa pun yang meninggalkan Makkah.",
    counterLabel: "putaran"
  }
};

// src/content/journeyHi.ts
var JOURNEY_META_HI = {
  umrah: {
    intro: "\u0909\u092E\u0930\u093E\u0939, \u091B\u094B\u091F\u0940 \u0939\u091C: \u090F\u0939\u0930\u093E\u092E, \u0924\u0935\u093E\u092B\u093C, \u0938\u0908, \u092B\u093F\u0930 \u0938\u093F\u0930 \u092E\u0941\u0902\u0921\u093E\u0928\u093E \u092F\u093E \u092C\u093E\u0932 \u0915\u091F\u0935\u093E\u0928\u093E\u0964 \u092F\u0939 \u0938\u093E\u0932 \u0915\u0947 \u0915\u093F\u0938\u0940 \u092D\u0940 \u0938\u092E\u092F \u0905\u0926\u093E \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948\u0964"
  },
  hajj: {
    intro: "\u0939\u091C, \u092C\u0921\u093C\u0940 \u0939\u091C, 8 \u0938\u0947 13 \u091C\u093C\u093F\u0932-\u0939\u093F\u091C\u094D\u091C\u093E \u0924\u0915, \u091C\u093F\u0938\u0915\u093E \u0915\u0947\u0902\u0926\u094D\u0930 \u0905\u0930\u092B\u093C\u093E\u0924 \u092E\u0947\u0902 \u0935\u0941\u0915\u093C\u0942\u092B\u093C \u0939\u0948\u0964"
  }
};
var JOURNEY_STEPS_HI = {
  prepare: {
    title: "\u0924\u0948\u092F\u093E\u0930\u0940 \u0914\u0930 \u0928\u0940\u092F\u0924",
    short: "\u092E\u0940\u0915\u093C\u093E\u0924 \u092A\u093E\u0930 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u090F\u0939\u0930\u093E\u092E \u092A\u0939\u0928\u0947\u0902",
    detail: "\u0928\u093E\u0916\u093C\u0942\u0928 \u0914\u0930 \u092C\u093E\u0932 \u0915\u093E\u091F\u0947\u0902, \u0917\u093C\u0941\u0938\u094D\u0932 \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0905\u092A\u0928\u0940 \u092F\u093E\u0924\u094D\u0930\u093E \u0915\u0940 \u0926\u093F\u0936\u093E \u0915\u0947 \u092E\u0940\u0915\u093C\u093E\u0924 \u0938\u0947 \u092A\u0939\u0932\u0947 \u090F\u0939\u0930\u093E\u092E \u0915\u0947 \u0915\u092A\u0921\u093C\u0947 \u092A\u0939\u0928\u0947\u0902\u0964 \u092B\u093F\u0930 \u0926\u093F\u0932 \u092E\u0947\u0902 \u0909\u092E\u0930\u093E\u0939 \u0915\u0940 \u0928\u0940\u092F\u0924 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0924\u0932\u092C\u093F\u092F\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964 \u090F\u0939\u0930\u093E\u092E \u092E\u0947\u0902 \u0930\u0939\u0924\u0947 \u0939\u0941\u090F \u092C\u093E\u0932 \u092F\u093E \u0928\u093E\u0916\u093C\u0942\u0928 \u0928 \u0915\u093E\u091F\u0947\u0902, \u0938\u093F\u0932\u0947 \u0939\u0941\u090F \u0915\u092A\u0921\u093C\u0947 \u092F\u093E \u0916\u093C\u0941\u0936\u092C\u0942 (\u092A\u0941\u0930\u0941\u0937\u094B\u0902 \u0915\u0947 \u0932\u093F\u090F) \u0928 \u092A\u0939\u0928\u0947\u0902, \u0936\u093F\u0915\u093E\u0930 \u0928 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0928\u093F\u0915\u093E\u0939 \u0915\u093E \u0905\u0915\u093C\u094D\u0926 \u0928 \u0915\u0930\u0947\u0902 \u2014 \u090F\u0939\u0930\u093E\u092E \u0915\u094B \u0915\u094D\u092F\u093E \u0924\u094B\u0921\u093C\u0924\u093E \u0939\u0948 \u0914\u0930 \u0909\u0938\u0915\u093E \u0915\u092B\u093C\u094D\u092B\u093C\u093E\u0930\u093E \u0915\u094D\u092F\u093E \u0939\u0948, \u0907\u0938\u0915\u093E \u0935\u093F\u0935\u0930\u0923 \u092E\u091C\u093C\u0939\u092C\u094B\u0902 \u092E\u0947\u0902 \u092D\u093F\u0928\u094D\u0928 \u0939\u0948, \u0924\u094B \u0905\u092A\u0928\u093E \u092E\u093E\u092E\u0932\u093E \u0915\u093F\u0938\u0940 \u092D\u0930\u094B\u0938\u0947\u092E\u0902\u0926 \u0935\u093F\u0926\u094D\u0935\u093E\u0928 \u0938\u0947 \u092A\u0915\u094D\u0915\u093E \u0915\u0930\u0947\u0902\u0964"
  },
  talbiyah: {
    title: "\u0924\u0932\u092C\u093F\u092F\u093E",
    short: "\u0939\u0930\u092E \u0924\u0915 \u092A\u0939\u0941\u0901\u091A\u0928\u0947 \u0924\u0915 \u0907\u0938\u0947 \u0926\u094B\u0939\u0930\u093E\u0924\u0947 \u0930\u0939\u0947\u0902",
    detail: "\xAB\u0932\u092C\u094D\u092C\u0948\u0915 \u0905\u0932\u094D\u0932\u093E\u0939\u0941\u092E\u094D\u092E\u093E \u0932\u092C\u094D\u092C\u0948\u0915, \u0932\u092C\u094D\u092C\u0948\u0915 \u0932\u093E \u0936\u0930\u0940\u0915\u093E \u0932\u0915\u093E \u0932\u092C\u094D\u092C\u0948\u0915, \u0907\u0928\u094D\u0928-\u0905\u0932-\u0939\u092E\u094D\u0926\u093E \u0935\u0928-\u0928\u093F\u2018\u092E\u0924\u093E \u0932\u0915\u093E \u0935\u0932-\u092E\u0941\u0932\u094D\u0915, \u0932\u093E \u0936\u0930\u0940\u0915\u093E \u0932\u0915\u0964\xBB \u092A\u0941\u0930\u0941\u0937 \u0907\u0938\u0947 \u090A\u0901\u091A\u0940 \u0906\u0935\u093E\u091C\u093C \u092E\u0947\u0902 \u0915\u0939\u0924\u0947 \u0939\u0948\u0902; \u092E\u0939\u093F\u0932\u093E\u090F\u0901 \u0927\u0940\u092E\u0947 \u0938\u094D\u0935\u0930 \u092E\u0947\u0902\u0964 \u0924\u0935\u093E\u092B\u093C \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0924\u0915 \u091C\u093E\u0930\u0940 \u0930\u0916\u0947\u0902\u0964"
  },
  tawaf: {
    title: "\u0915\u093E\u092C\u093E \u0915\u093E \u0924\u0935\u093E\u092B\u093C",
    short: "\u0938\u093E\u0924 \u091A\u0915\u094D\u0915\u0930, \u0939\u091C\u0930-\u090F-\u0905\u0938\u094D\u0935\u0926 \u0938\u0947 \u0936\u0941\u0930\u0942",
    detail: "\u0939\u091C\u0930-\u090F-\u0905\u0938\u094D\u0935\u0926 \u0938\u0947 \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0928\u0940\u092F\u0924 \u0938\u0947 \u0906\u0917\u0947 \u092C\u0922\u093C\u0947\u0902, \u092B\u093F\u0930 \u0915\u093E\u092C\u093E \u0915\u0947 \u0938\u093E\u0924 \u091A\u0915\u094D\u0915\u0930 \u0932\u0917\u093E\u090F\u0901, \u0915\u093E\u092C\u093E \u0906\u092A\u0915\u0940 \u092C\u093E\u0908\u0902 \u0913\u0930 \u0930\u0939\u0947\u0964 \u0939\u0930 \u092C\u093E\u0930 \u091C\u092C \u0906\u092A \u0909\u0938\u0915\u0947 \u092A\u093E\u0938 \u0938\u0947 \u0917\u0941\u091C\u093C\u0930\u0947\u0902, \u0939\u091C\u0930-\u090F-\u0905\u0938\u094D\u0935\u0926 \u0915\u094B \u091B\u0941\u090F\u0901 \u092F\u093E \u0909\u0938\u0915\u0940 \u0913\u0930 \u0907\u0936\u093E\u0930\u093E \u0915\u0930\u0947\u0902, \u0914\u0930 \u091C\u094B \u091C\u093C\u093F\u0915\u094D\u0930 \u092F\u093E \u0915\u093C\u0941\u0930\u0906\u0928 \u0906\u0938\u093E\u0928 \u0939\u094B \u092A\u0922\u093C\u0947\u0902 \u2014 \u0939\u0930 \u091A\u0915\u094D\u0915\u0930 \u0915\u0947 \u0932\u093F\u090F \u0915\u094B\u0908 \u0935\u093F\u0936\u0947\u0937 \u0926\u0941\u0906 \u0928\u093F\u0936\u094D\u091A\u093F\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u092A\u0941\u0930\u0941\u0937 \u092A\u0939\u0932\u0947 \u0924\u0940\u0928 \u091A\u0915\u094D\u0915\u0930\u094B\u0902 \u092E\u0947\u0902 \u0924\u0947\u091C\u093C \u091A\u0932\u0924\u0947 \u0939\u0948\u0902\u0964 \u092A\u0942\u0930\u093E \u0915\u0930\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u092F\u0926\u093F \u0938\u0902\u092D\u0935 \u0939\u094B \u0924\u094B \u092E\u0915\u093C\u093E\u092E-\u090F-\u0907\u092C\u094D\u0930\u093E\u0939\u0940\u092E \u0915\u0947 \u092A\u0940\u091B\u0947 \u0926\u094B \u0930\u0915\u093E\u0924 \u0928\u092E\u093E\u091C\u093C \u092A\u0922\u093C\u0947\u0902, \u092B\u093F\u0930 \u091C\u093C\u092E\u091C\u093C\u092E \u092A\u093F\u090F\u0901\u0964",
    counterLabel: "\u091A\u0915\u094D\u0915\u0930"
  },
  sai: {
    title: "\u0938\u092B\u093C\u093E \u0914\u0930 \u092E\u0930\u0935\u093E \u0915\u0947 \u092C\u0940\u091A \u0938\u0908",
    short: "\u0926\u094B\u0928\u094B\u0902 \u092A\u0939\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u0947 \u092C\u0940\u091A \u0938\u093E\u0924 \u092C\u093E\u0930",
    detail: "\u0938\u092B\u093C\u093E \u0938\u0947 \u092E\u0930\u0935\u093E \u0924\u0915 \u091A\u0932\u0947\u0902 \u2014 \u092F\u0939 \u090F\u0915 \u091A\u0915\u094D\u0915\u0930 \u0939\u0941\u0906 \u2014 \u092B\u093F\u0930 \u0932\u094C\u091F\u0947\u0902, \u0915\u0941\u0932 \u0938\u093E\u0924, \u0914\u0930 \u092E\u0930\u0935\u093E \u092A\u0930 \u0938\u092E\u093E\u092A\u094D\u0924 \u0915\u0930\u0947\u0902\u0964 \u0938\u0908 \u0905\u092A\u0928\u0940 \u091C\u0917\u0939 \u090F\u0915 \u0938\u094D\u0935\u0924\u0902\u0924\u094D\u0930 \u092E\u0928\u0938\u093F\u0915 \u0939\u0948 \u0914\u0930 \u0907\u0938\u0947 \u091B\u094B\u091F\u093E \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E\u0924\u093E\u0964 \u0905\u092A\u0928\u0940 \u0938\u093E\u092E\u0930\u094D\u0925\u094D\u092F \u0915\u0947 \u0905\u0928\u0941\u0938\u093E\u0930 \u091A\u0932\u0947\u0902; \u0915\u0947\u0935\u0932 \u0926\u094B\u0928\u094B\u0902 \u0939\u0930\u0947 \u0928\u093F\u0936\u093E\u0928\u094B\u0902 \u0915\u0947 \u092C\u0940\u091A \u0915\u093E \u0939\u093F\u0938\u094D\u0938\u093E \u0924\u0947\u091C\u093C \u091A\u0932\u0915\u0930 \u092A\u093E\u0930 \u0915\u093F\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948\u0964",
    counterLabel: "\u091A\u0915\u094D\u0915\u0930"
  },
  halq: {
    title: "\u0938\u093F\u0930 \u092E\u0941\u0902\u0921\u093E\u0928\u093E \u092F\u093E \u092C\u093E\u0932 \u0915\u091F\u0935\u093E\u0928\u093E",
    short: "\u091C\u094B \u0915\u0926\u092E \u0906\u092A\u0915\u094B \u090F\u0939\u0930\u093E\u092E \u0938\u0947 \u092E\u0941\u0915\u094D\u0924 \u0915\u0930\u0924\u093E \u0939\u0948",
    detail: "\u092A\u0941\u0930\u0941\u0937 \u0938\u093F\u0930 \u092E\u0941\u0902\u0921\u093E\u090F\u0901 \u092F\u093E \u0938\u092C \u0913\u0930 \u0938\u0947 \u092C\u093E\u0932 \u091B\u094B\u091F\u0947 \u0915\u0930\u093E\u090F\u0901; \u092E\u0941\u0902\u0921\u093E\u0928\u093E \u092C\u0947\u0939\u0924\u0930 \u0939\u0948\u0964 \u092E\u0939\u093F\u0932\u093E\u090F\u0901 \u092C\u093E\u0932\u094B\u0902 \u0915\u0947 \u0938\u093F\u0930\u094B\u0902 \u0938\u0947 \u090F\u0915 \u0909\u0901\u0917\u0932\u0940 \u0915\u0947 \u092A\u094B\u0930 \u0915\u0947 \u092C\u0930\u093E\u092C\u0930 \u0915\u093E\u091F\u0947\u0902\u0964 \u0907\u0938\u0915\u0947 \u0938\u093E\u0925 \u0909\u092E\u0930\u093E\u0939 \u092A\u0942\u0930\u094D\u0923 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948 \u0914\u0930 \u090F\u0939\u0930\u093E\u092E \u0928\u0947 \u091C\u094B \u0915\u0941\u091B \u0930\u094B\u0915\u093E \u0925\u093E \u0935\u0939 \u092B\u093F\u0930 \u0939\u0932\u093E\u0932 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948\u0964"
  },
  closing: {
    title: "\u092F\u093E\u0926 \u0915\u0930\u0947\u0902, \u0914\u0930 \u092F\u093E\u0924\u094D\u0930\u093E \u092A\u0942\u0930\u0940 \u0915\u0930\u0947\u0902",
    short: "\u0926\u094B \u0930\u0915\u093E\u0924 \u092A\u0922\u093C\u0947\u0902 \u0914\u0930 \u0936\u0941\u0915\u094D\u0930 \u0905\u0926\u093E \u0915\u0930\u0947\u0902",
    detail: "\u0939\u0930\u092E \u092E\u0947\u0902 \u091C\u0939\u093E\u0901 \u0938\u0902\u092D\u0935 \u0939\u094B \u0928\u092E\u093E\u091C\u093C \u092A\u0922\u093C\u0947\u0902, \u092F\u0926\u093F \u0938\u093E\u092E\u0930\u094D\u0925\u094D\u092F \u0939\u094B \u0924\u094B \u0938\u0926\u0915\u093C\u093E \u0926\u0947\u0902, \u0914\u0930 \u092A\u0942\u0930\u0947 \u092E\u0928\u0938\u093F\u0915 \u0915\u0947 \u092C\u093E\u0926 \u0915\u0940 \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0940 \u0926\u0941\u0906 \u0915\u094B \u0905\u092A\u0928\u093E\u090F\u0901\u0964 \u092C\u0939\u0941\u0924 \u0938\u0947 \u0932\u094B\u0917 \u092B\u093F\u0930 \u0905\u0932-\u0924\u0928\u2018\u0908\u092E \u0938\u0947 \u0909\u092E\u0930\u093E\u0939 \u0926\u094B\u0939\u0930\u093E\u0924\u0947 \u0939\u0948\u0902 \u092F\u093E \u0915\u093F\u0938\u0940 \u0914\u0930 \u0915\u0940 \u0913\u0930 \u0938\u0947 \u0905\u0926\u093E \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u2014 \u092F\u0939 \u0906\u092A\u0915\u0940 \u0905\u092A\u0928\u0940 \u0928\u0940\u092F\u0924 \u0914\u0930 \u0938\u093E\u092E\u0930\u094D\u0925\u094D\u092F \u0915\u093E \u0935\u093F\u0937\u092F \u0939\u0948\u0964"
  },
  intention: {
    title: "\u0905\u092A\u0928\u0947 \u0939\u091C \u0915\u093E \u092A\u094D\u0930\u0915\u093E\u0930 \u091A\u0941\u0928\u0947\u0902",
    short: "\u0924\u092E\u0924\u094D\u0924\u0941\u2018, \u0915\u093C\u093F\u0930\u093E\u0928, \u092F\u093E \u0907\u092B\u093C\u0930\u093E\u0926",
    detail: "\u0924\u092E\u0924\u094D\u0924\u0941\u2018: \u0909\u092E\u0930\u093E\u0939 \u0915\u093E \u090F\u0939\u0930\u093E\u092E \u092C\u093E\u0901\u0927\u0947\u0902, \u0909\u0938\u0947 \u092A\u0942\u0930\u093E \u0915\u0930\u0947\u0902, \u090F\u0939\u0930\u093E\u092E \u0916\u094B\u0932 \u0926\u0947\u0902, \u092B\u093F\u0930 8 \u0924\u093E\u0930\u0940\u0916\u093C \u0915\u094B \u0939\u091C \u0915\u0947 \u0932\u093F\u090F \u0926\u094B\u092C\u093E\u0930\u093E \u090F\u0939\u0930\u093E\u092E \u092C\u093E\u0901\u0927\u0947\u0902; \u0907\u0938\u092E\u0947\u0902 \u0915\u093C\u0941\u0930\u092C\u093E\u0928\u0940 \u0915\u093E \u091C\u093E\u0928\u0935\u0930 \u0936\u093E\u092E\u093F\u0932 \u0939\u0948\u0964 \u0915\u093C\u093F\u0930\u093E\u0928: \u0909\u092E\u0930\u093E\u0939 \u0914\u0930 \u0939\u091C \u0926\u094B\u0928\u094B\u0902 \u0915\u094B \u090F\u0915 \u0939\u0940 \u090F\u0939\u0930\u093E\u092E \u092E\u0947\u0902 \u0930\u0916\u0947\u0902\u0964 \u0907\u092B\u093C\u0930\u093E\u0926: \u0915\u0947\u0935\u0932 \u0939\u091C \u0915\u093E \u090F\u0939\u0930\u093E\u092E \u092C\u093E\u0901\u0927\u0947\u0902 \u0914\u0930 \u092A\u0942\u0930\u0947 \u0938\u092E\u092F \u090F\u0939\u0930\u093E\u092E \u092E\u0947\u0902 \u0930\u0939\u0947\u0902\u0964 \u0915\u094C\u0928 \u092C\u0947\u0939\u0924\u0930 \u0939\u0948, \u0914\u0930 \u0939\u0930 \u090F\u0915 \u092E\u0947\u0902 \u0915\u094D\u092F\u093E \u0932\u093E\u091C\u093C\u093F\u092E \u0939\u0948, \u092F\u0939 \u0906\u092A\u0915\u0940 \u092A\u0930\u093F\u0938\u094D\u0925\u093F\u0924\u093F \u0914\u0930 \u092E\u091C\u093C\u0939\u092C \u092A\u0930 \u0928\u093F\u0930\u094D\u092D\u0930 \u0915\u0930\u0924\u093E \u0939\u0948 \u2014 \u092F\u093E\u0924\u094D\u0930\u093E \u0938\u0947 \u092A\u0939\u0932\u0947 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0915\u0947 \u0938\u093E\u0925 \u0924\u092F \u0915\u0930\u0947\u0902\u0964"
  },
  ihram: {
    title: "\u090F\u0939\u0930\u093E\u092E \u092C\u093E\u0901\u0927\u0928\u093E",
    short: "\u0917\u093C\u0941\u0938\u094D\u0932 \u0915\u0930\u0947\u0902, \u0915\u092A\u0921\u093C\u0947 \u092A\u0939\u0928\u0947\u0902, \u0928\u0940\u092F\u0924 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0924\u0932\u092C\u093F\u092F\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902",
    detail: "\u0917\u093C\u0941\u0938\u094D\u0932 \u0915\u0930\u0947\u0902 \u0914\u0930 \u090F\u0939\u0930\u093E\u092E \u0915\u0947 \u0915\u092A\u0921\u093C\u0947 \u092A\u0939\u0928\u0947\u0902, \u092B\u093F\u0930 \u0905\u092A\u0928\u0940 \u091A\u0941\u0928\u0940 \u0939\u0941\u0908 \u092E\u0928\u093E\u0938\u093F\u0915 \u0915\u0940 \u0928\u0940\u092F\u0924 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0924\u0932\u092C\u093F\u092F\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964 \u0905\u092C \u090F\u0939\u0930\u093E\u092E \u0915\u0940 \u092E\u0928\u093E\u0939\u093F\u092F\u093E\u0901 \u0932\u093E\u0917\u0942 \u0939\u094B \u091C\u093E\u0924\u0940 \u0939\u0948\u0902, \u091C\u092C \u0924\u0915 \u0906\u092A \u0930\u092E\u0940 \u0928 \u0915\u0930 \u0932\u0947\u0902, \u0915\u093C\u0941\u0930\u092C\u093E\u0928\u0940 \u0928 \u0915\u0930 \u0932\u0947\u0902 \u0914\u0930 \u0938\u093F\u0930 \u0928 \u092E\u0941\u0902\u0921\u093E \u0932\u0947\u0902 \u092F\u093E \u092C\u093E\u0932 \u0928 \u0915\u091F\u0935\u093E \u0932\u0947\u0902\u0964"
  },
  qudum: {
    title: "\u0906\u0917\u092E\u0928 \u0915\u093E \u0924\u0935\u093E\u092B\u093C \u0914\u0930 \u0938\u0908",
    short: "\u0924\u0935\u093E\u092B\u093C-\u090F-\u0915\u093C\u0941\u0926\u0942\u092E, \u092B\u093F\u0930 \u0924\u092E\u0924\u094D\u0924\u0941\u2018 \u0915\u0947 \u0932\u093F\u090F \u0938\u0908",
    detail: "\u092E\u0915\u094D\u0915\u093E \u092A\u0939\u0941\u0901\u091A\u0915\u0930 \u0938\u093E\u0924 \u091A\u0915\u094D\u0915\u0930\u094B\u0902 \u0915\u093E \u0906\u0917\u092E\u0928 \u0924\u0935\u093E\u092B\u093C \u0915\u0930\u0947\u0902 \u0914\u0930 \u0926\u094B \u0930\u0915\u093E\u0924 \u092A\u0922\u093C\u0947\u0902\u0964 \u0924\u092E\u0924\u094D\u0924\u0941\u2018 \u092E\u0947\u0902 \u0907\u0938\u0915\u0947 \u092C\u093E\u0926 \u0939\u091C \u0915\u0940 \u0938\u0908 \u0915\u0930\u0947\u0902 (\u092F\u093E \u0938\u0908 \u0915\u094B \u0924\u0935\u093E\u092B\u093C-\u090F-\u0907\u092B\u093C\u093E\u091C\u093C\u093E \u0915\u0947 \u092C\u093E\u0926 \u0915\u0947 \u0932\u093F\u090F \u0930\u0916\u0947\u0902 \u2014 \u0926\u094B\u0928\u094B\u0902 \u0915\u094B \u092D\u093F\u0928\u094D\u0928 \u092E\u091C\u093C\u0939\u092C\u094B\u0902 \u0928\u0947 \u092E\u093E\u0928\u094D\u092F \u0920\u0939\u0930\u093E\u092F\u093E \u0939\u0948)\u0964 \u0907\u0938\u0915\u0947 \u092C\u093E\u0926 \u0906\u092A \u090F\u0939\u0930\u093E\u092E \u092E\u0947\u0902 \u0939\u0940 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964",
    counterLabel: "\u091A\u0915\u094D\u0915\u0930"
  },
  tarwiyah: {
    title: "8 \u091C\u093C\u093F\u0932-\u0939\u093F\u091C\u094D\u091C\u093E \u2014 \u092E\u093F\u0928\u093E",
    short: "\u092F\u094C\u092E-\u090F-\u0924\u0930\u0935\u093F\u092F\u093E, \u092E\u093F\u0928\u093E \u092E\u0947\u0902 \u092C\u093F\u0924\u093E\u092F\u093E \u0917\u092F\u093E",
    detail: "\u092F\u0926\u093F \u0906\u092A\u0928\u0947 \u090F\u0939\u0930\u093E\u092E \u0916\u094B\u0932 \u0932\u093F\u092F\u093E \u0939\u0948 \u0924\u094B \u0939\u091C \u0915\u0947 \u0932\u093F\u090F \u0926\u094B\u092C\u093E\u0930\u093E \u090F\u0939\u0930\u093E\u092E \u092C\u093E\u0901\u0927\u0947\u0902, \u0914\u0930 \u092E\u093F\u0928\u093E \u091C\u093E\u090F\u0901, \u0935\u0939\u093E\u0901 \u091C\u093C\u0941\u0939\u0930, \u0905\u0938\u094D\u0930, \u092E\u0917\u093C\u0930\u093F\u092C, \u0907\u0936\u093E \u0914\u0930 \u092B\u093C\u091C\u094D\u0930 \u092A\u0922\u093C\u0947\u0902 \u2014 \u0939\u0930 \u090F\u0915 \u0926\u094B \u0930\u0915\u093E\u0924 \u0915\u0930\u0915\u0947, \u092A\u0930 \u0907\u0915\u091F\u094D\u0920\u093E \u0928\u0939\u0940\u0902\u0964 \u0905\u0930\u092B\u093C\u093E\u0924 \u091C\u093E\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0930\u093E\u0924 \u092E\u093F\u0928\u093E \u092E\u0947\u0902 \u092C\u093F\u0924\u093E\u090F\u0901\u0964"
  },
  arafah: {
    title: "9 \u091C\u093C\u093F\u0932-\u0939\u093F\u091C\u094D\u091C\u093E \u2014 \u0905\u0930\u092B\u093C\u093E\u0924",
    short: "\u0935\u0939 \u0935\u0941\u0915\u093C\u0942\u092B\u093C \u091C\u094B \u0938\u094D\u0935\u092F\u0902 \u0939\u091C \u0939\u0948",
    detail: "\u0938\u0942\u0930\u094D\u092F\u094B\u0926\u092F \u0915\u0947 \u092C\u093E\u0926 \u0905\u0930\u092B\u093C\u093E\u0924 \u091C\u093E\u090F\u0901 \u0914\u0930 \u0926\u094B\u092A\u0939\u0930 \u0938\u0947 \u0938\u0942\u0930\u094D\u092F\u093E\u0938\u094D\u0924 \u0924\u0915 \u0935\u0939\u093E\u0901 \u0920\u0939\u0930\u0947\u0902, \u091C\u093C\u0941\u0939\u0930 \u0914\u0930 \u0905\u0938\u094D\u0930 \u0915\u094B \u0907\u0915\u091F\u094D\u0920\u093E \u0914\u0930 \u091B\u094B\u091F\u093E \u0915\u0930\u0915\u0947 \u092A\u0922\u093C\u0947\u0902\u0964 \u0905\u0930\u092B\u093C\u093E\u0924 \u0915\u093E \u0938\u092E\u094D\u092A\u0942\u0930\u094D\u0923 \u092E\u0948\u0926\u093E\u0928 \u0935\u0941\u0915\u093C\u0942\u092B\u093C \u0915\u0940 \u091C\u0917\u0939 \u0939\u0948, \u0939\u093E\u0932\u093E\u0901\u0915\u093F \u091C\u092C\u0932-\u090F-\u0930\u0939\u092E\u0924 \u0915\u0940 \u091A\u091F\u094D\u091F\u093E\u0928 \u092A\u0930 \u0932\u094B\u0917 \u0907\u0915\u091F\u094D\u0920\u093E \u0939\u094B\u0924\u0947 \u0939\u0948\u0902\u0964 \u0926\u093F\u0928 \u092D\u0930 \u0924\u0932\u092C\u093F\u092F\u093E, \u091C\u093C\u093F\u0915\u094D\u0930, \u0915\u093C\u0941\u0930\u0906\u0928, \u0924\u094C\u092C\u093E \u0914\u0930 \u0926\u0941\u0906 \u092E\u0947\u0902 \u0917\u0941\u091C\u093C\u093E\u0930\u0947\u0902 \u2014 \u092F\u0939\u0940 \u0935\u0939 \u0926\u093F\u0928 \u0939\u0948 \u091C\u093F\u0938 \u092A\u0930 \u0939\u091C \u091F\u093F\u0915\u093E \u0939\u0948\u0964"
  },
  muzdalifah: {
    title: "\u092E\u0941\u091C\u093C\u094D\u0926\u0932\u093F\u092B\u093C\u093E \u0915\u0940 \u0930\u093E\u0924",
    short: "\u0938\u0942\u0930\u094D\u092F\u093E\u0938\u094D\u0924 \u0915\u0947 \u092C\u093E\u0926 \u0928\u093F\u0915\u0932\u0947\u0902, \u0928\u092E\u093E\u091C\u093C \u092A\u0922\u093C\u0947\u0902 \u0914\u0930 \u0915\u0902\u0915\u0921\u093C \u091A\u0941\u0928\u0947\u0902",
    detail: "\u0938\u0942\u0930\u094D\u092F\u093E\u0938\u094D\u0924 \u0915\u0947 \u092C\u093E\u0926 \u2014 \u0938\u0941\u092C\u0939 \u0938\u0947 \u092A\u0939\u0932\u0947 \u2014 \u0905\u0930\u092B\u093C\u093E\u0924 \u0938\u0947 \u0928\u093F\u0915\u0932\u0947\u0902 \u0914\u0930 \u092E\u0941\u091C\u093C\u094D\u0926\u0932\u093F\u092B\u093C\u093E \u091C\u093E\u090F\u0901, \u091C\u0939\u093E\u0901 \u092E\u0917\u093C\u0930\u093F\u092C \u0914\u0930 \u0907\u0936\u093E \u0907\u0915\u091F\u094D\u0920\u093E \u092A\u0922\u093C\u0947\u0902 \u0914\u0930 \u0930\u093E\u0924 \u092C\u093F\u0924\u093E\u090F\u0901\u0964 \u0930\u092E\u0940 \u0915\u0947 \u0915\u0902\u0915\u0921\u093C \u092F\u0939\u0940\u0902 \u0907\u0915\u091F\u094D\u0920\u093E \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0938\u0941\u092C\u0939 \u0938\u0947 \u092A\u0939\u0932\u0947 \u092F\u093E \u0909\u0938\u0915\u0947 \u0906\u0938-\u092A\u093E\u0938 \u092E\u093F\u0928\u093E \u0915\u0947 \u0932\u093F\u090F \u0928\u093F\u0915\u0932\u0947\u0902\u0964"
  },
  aqaba: {
    title: "10 \u0924\u093E\u0930\u0940\u0916\u093C \u2014 \u092C\u0921\u093C\u0947 \u091C\u092E\u0930\u0947 \u0915\u0940 \u0930\u092E\u0940",
    short: "\u091C\u092E\u0930\u093E-\u090F-\u0905\u0915\u093C\u092C\u093E \u092A\u0930 \u0938\u093E\u0924 \u0915\u0902\u0915\u0921\u093C",
    detail: "\u092E\u093F\u0928\u093E \u092E\u0947\u0902 \u092C\u0921\u093C\u0947 \u091C\u092E\u0930\u0947 (\u0905\u0915\u093C\u092C\u093E, \u091C\u094B \u092E\u0915\u094D\u0915\u093E \u0915\u0947 \u0938\u092C\u0938\u0947 \u0928\u093F\u0915\u091F \u0939\u0948) \u092A\u0930 \u0938\u093E\u0924 \u0915\u0902\u0915\u0921\u093C \u092E\u093E\u0930\u0947\u0902, \u0939\u0930 \u092B\u0947\u0902\u0915 \u092A\u0930 \xAB\u0905\u0932\u094D\u0932\u093E\u0939\u0941 \u0905\u0915\u092C\u0930\xBB \u0915\u0939\u0924\u0947 \u0939\u0941\u090F\u0964 \u0907\u0938 \u0930\u092E\u0940 \u0938\u0947 \u090F\u0939\u0930\u093E\u092E \u0915\u0940 \u092C\u0921\u093C\u0940 \u091B\u0942\u091F \u0932\u093E\u0917\u0942 \u0939\u094B\u0924\u0940 \u0939\u0948\u0964",
    counterLabel: "\u0915\u0902\u0915\u0921\u093C"
  },
  hady: {
    title: "10 \u0924\u093E\u0930\u0940\u0916\u093C \u2014 \u0915\u093C\u0941\u0930\u092C\u093E\u0928\u0940 \u0914\u0930 \u0939\u0932\u0915\u093C",
    short: "\u0939\u0926\u0940, \u092B\u093F\u0930 \u092E\u0941\u0902\u0921\u093E\u0928\u093E \u092F\u093E \u0915\u091F\u0935\u093E\u0928\u093E",
    detail: "\u0924\u092E\u0924\u094D\u0924\u0941\u2018 \u0914\u0930 \u0915\u093C\u093F\u0930\u093E\u0928 \u0915\u0947 \u0932\u093F\u090F \u091C\u094B \u0915\u093C\u0941\u0930\u092C\u093E\u0928\u0940 \u0915\u093E \u091C\u093E\u0928\u0935\u0930 \u0932\u093E\u091C\u093C\u093F\u092E \u0939\u0948 \u0909\u0938\u0947 \u092A\u0947\u0936 \u0915\u0930\u0947\u0902 \u2014 \u0906\u091C \u0905\u0927\u093F\u0915\u093E\u0902\u0936 \u0939\u093E\u091C\u0940 \u0905\u0927\u093F\u0915\u0943\u0924 \u090F\u091C\u0947\u0902\u091F \u0928\u093F\u092F\u0941\u0915\u094D\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u091C\u094B \u092E\u093E\u0928\u094D\u092F \u0939\u0948\u0964 \u092B\u093F\u0930 \u0938\u093F\u0930 \u092E\u0941\u0902\u0921\u093E\u090F\u0901 \u092F\u093E \u092C\u093E\u0932 \u091B\u094B\u091F\u0947 \u0915\u0930\u093E\u090F\u0901; \u092E\u0939\u093F\u0932\u093E\u090F\u0901 \u090F\u0915 \u0909\u0901\u0917\u0932\u0940 \u0915\u0947 \u092A\u094B\u0930 \u0915\u0947 \u092C\u0930\u093E\u092C\u0930 \u0915\u093E\u091F\u0947\u0902\u0964 \u0930\u092E\u0940, \u0915\u093C\u0941\u0930\u092C\u093E\u0928\u0940 \u0914\u0930 \u0939\u0932\u0915\u093C \u092A\u0942\u0930\u0947 \u0939\u094B \u091C\u093E\u0928\u0947 \u092A\u0930 \u090F\u0939\u0930\u093E\u092E \u0928\u0947 \u091C\u094B \u0915\u0941\u091B \u0930\u094B\u0915\u093E \u0925\u093E \u0935\u0939 \u0939\u0932\u093E\u0932 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948, \u0938\u093F\u0935\u093E\u092F \u092A\u0924\u093F-\u092A\u0924\u094D\u0928\u0940 \u0915\u0947 \u0938\u0902\u092C\u0902\u0927 \u0915\u0947\u0964"
  },
  ifadah: {
    title: "10 \u0938\u0947 12 \u0924\u093E\u0930\u0940\u0916\u093C \u2014 \u0924\u0935\u093E\u092B\u093C-\u090F-\u0907\u092B\u093C\u093E\u091C\u093C\u093E",
    short: "\u0939\u091C \u0915\u093E \u0930\u0941\u0915\u094D\u0928, \u0914\u0930 \u092F\u0926\u093F \u092C\u093E\u0915\u093C\u0940 \u0939\u094B \u0924\u094B \u0938\u0908",
    detail: "\u092E\u0915\u094D\u0915\u093E \u0932\u094C\u091F\u0915\u0930 \u0938\u093E\u0924 \u091A\u0915\u094D\u0915\u0930\u094B\u0902 \u0915\u093E \u0924\u0935\u093E\u092B\u093C-\u090F-\u0907\u092B\u093C\u093E\u091C\u093C\u093E \u0915\u0930\u0947\u0902, \u0914\u0930 \u092F\u0926\u093F \u0906\u092A\u0928\u0947 \u0939\u091C \u0915\u0940 \u0938\u0908 \u092A\u0939\u0932\u0947 \u0928\u0939\u0940\u0902 \u0915\u0940 \u0939\u0948 \u0924\u094B \u0909\u0938\u0915\u0947 \u092C\u093E\u0926 \u0938\u0908 \u0915\u0930\u0947\u0902\u0964 \u092F\u0939\u0940 \u0924\u0935\u093E\u092B\u093C \u0935\u0939 \u0930\u0941\u0915\u094D\u0928 \u0939\u0948 \u091C\u094B \u0924\u092F \u0915\u0930\u0924\u093E \u0939\u0948: \u0907\u0938\u0915\u0947 \u092C\u093F\u0928\u093E \u0939\u091C \u092A\u0942\u0930\u093E \u0928\u0939\u0940\u0902 \u0939\u094B\u0924\u093E\u0964",
    counterLabel: "\u091A\u0915\u094D\u0915\u0930"
  },
  tashreeq: {
    title: "11 \u0938\u0947 13 \u0924\u093E\u0930\u0940\u0916\u093C \u2014 \u0924\u0936\u0930\u0940\u0915\u093C \u0915\u0947 \u0926\u093F\u0928",
    short: "\u0939\u0930 \u0926\u094B\u092A\u0939\u0930 \u0924\u0940\u0928\u094B\u0902 \u091C\u092E\u0930\u0947, \u092B\u093F\u0930 \u092E\u093F\u0928\u093E",
    detail: "\u0939\u0930 \u0926\u094B\u092A\u0939\u0930 \u091C\u093C\u0935\u093E\u0932 \u0915\u0947 \u092C\u093E\u0926 \u0924\u0940\u0928\u094B\u0902 \u091C\u092E\u0930\u094B\u0902 \u092A\u0930 \u0915\u094D\u0930\u092E \u0938\u0947 \u0915\u0902\u0915\u0921\u093C \u092E\u093E\u0930\u0947\u0902 \u2014 \u091B\u094B\u091F\u093E, \u092B\u093F\u0930 \u092E\u0927\u094D\u092F, \u092B\u093F\u0930 \u092C\u0921\u093C\u093E \u2014 \u0939\u0930 \u090F\u0915 \u092A\u0930 \u0938\u093E\u0924 \u0915\u0902\u0915\u0921\u093C, \u0939\u0930 \u092B\u0947\u0902\u0915 \u092A\u0930 \xAB\u0905\u0932\u094D\u0932\u093E\u0939\u0941 \u0905\u0915\u092C\u0930\xBB \u0915\u0939\u0924\u0947 \u0939\u0941\u090F\u0964 \u092F\u0947 \u0930\u093E\u0924\u0947\u0902 \u092E\u093F\u0928\u093E \u092E\u0947\u0902 \u092C\u093F\u0924\u093E\u090F\u0901\u0964 \u091C\u094B 12 \u0924\u093E\u0930\u0940\u0916\u093C \u0915\u094B, \u0909\u0938 \u0926\u093F\u0928 \u0915\u0940 \u0930\u092E\u0940 \u0915\u0930\u0915\u0947 \u0928\u093F\u0915\u0932 \u091C\u093E\u0924\u093E \u0939\u0948, \u0909\u0938 \u092A\u0930 \u0915\u094B\u0908 \u0926\u094B\u0937 \u0928\u0939\u0940\u0902; \u0914\u0930 \u091C\u094B 13 \u0924\u093E\u0930\u0940\u0916\u093C \u0924\u0915 \u0930\u0939\u0924\u093E \u0939\u0948, \u0909\u0938 \u092A\u0930 \u092D\u0940 \u0915\u094B\u0908 \u0926\u094B\u0937 \u0928\u0939\u0940\u0902\u0964",
    counterLabel: "\u0915\u0902\u0915\u0921\u093C"
  },
  wada: {
    title: "\u0924\u0935\u093E\u092B\u093C-\u090F-\u0935\u093F\u0926\u093E",
    short: "\u092E\u0915\u094D\u0915\u093E \u091B\u094B\u0921\u093C\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0924\u0935\u093E\u092B\u093C-\u090F-\u0935\u093F\u0926\u093E",
    detail: "\u0918\u0930 \u0932\u094C\u091F\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0938\u093E\u0924 \u091A\u0915\u094D\u0915\u0930\u094B\u0902 \u0915\u093E \u0924\u0935\u093E\u092B\u093C-\u090F-\u0935\u093F\u0926\u093E \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0926\u094B \u0930\u0915\u093E\u0924 \u092A\u0922\u093C\u0947\u0902 \u0914\u0930 \u092A\u094D\u0930\u0938\u094D\u0925\u093E\u0928 \u0915\u0930\u0947\u0902\u0964 \u092E\u0915\u094D\u0915\u093E \u0938\u0947 \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0939\u0930 \u0935\u094D\u092F\u0915\u094D\u0924\u093F \u0915\u0947 \u0932\u093F\u090F \u092F\u0939\u0940 \u0939\u091C \u0915\u093E \u0905\u0902\u0924\u093F\u092E \u092E\u0928\u0938\u093F\u0915 \u0939\u0948\u0964",
    counterLabel: "\u091A\u0915\u094D\u0915\u0930"
  }
};

