function journeyMeta(kind, lang) {
  const code = typeof lang === "string" ? lang : lang === true ? "ar" : "en";
  const base = JOURNEY_META[kind];
  const table = code === "kk" ? JOURNEY_META_KK : code === "zh" ? JOURNEY_META_ZH : code === "uz" ? JOURNEY_META_UZ : code === "ta" ? JOURNEY_META_TA : code === "ms" ? JOURNEY_META_MS : code === "bn" ? JOURNEY_META_BN : code === "fr" ? JOURNEY_META_FR : code === "fa" ? JOURNEY_META_FA : code === "ru" ? JOURNEY_META_RU : code === "tr" ? JOURNEY_META_TR : code === "ur" ? JOURNEY_META_UR : code === "id" ? JOURNEY_META_ID : code === "hi" ? JOURNEY_META_HI : code === "ml" ? JOURNEY_META_ML : code === "ar" ? JOURNEY_META_AR : void 0;
  const own = table?.[kind];
  return own ? { ...base, intro: own.intro } : base;
}
function localizeJourneyStep(step, lang) {
  const code = typeof lang === "string" ? lang : lang === true ? "ar" : "en";
  const table = code === "kk" ? JOURNEY_STEPS_KK : code === "zh" ? JOURNEY_STEPS_ZH : code === "uz" ? JOURNEY_STEPS_UZ : code === "ta" ? JOURNEY_STEPS_TA : code === "ms" ? JOURNEY_STEPS_MS : code === "bn" ? JOURNEY_STEPS_BN : code === "fr" ? JOURNEY_STEPS_FR : code === "fa" ? JOURNEY_STEPS_FA : code === "ru" ? JOURNEY_STEPS_RU : code === "tr" ? JOURNEY_STEPS_TR : code === "ur" ? JOURNEY_STEPS_UR : code === "id" ? JOURNEY_STEPS_ID : code === "hi" ? JOURNEY_STEPS_HI : code === "ml" ? JOURNEY_STEPS_ML : code === "ar" ? JOURNEY_STEPS_AR : void 0;
  const own = table?.[step.id];
  if (!own) return step;
  return {
    ...step,
    title: own.title,
    short: own.short,
    detail: own.detail,
    counter: step.counter ? { ...step.counter, label: own.counterLabel || step.counter.label } : step.counter
  };
}

