  "Ministry of Hajj and Umrah": "\u049A\u0430\u0436\u044B\u043B\u044B\u049B \u0436\u04D9\u043D\u0435 \u0443\u043C\u0440\u0430 \u043C\u0438\u043D\u0438\u0441\u0442\u0440\u043B\u0456\u0433\u0456",
  "Missed": "\u049A\u0430\u0437\u0430 \u049B\u0430\u043B\u0493\u0430\u043D",
