  "Search opened collections": "\u0410\u0448\u044B\u043B\u0493\u0430\u043D \u0436\u0438\u043D\u0430\u049B\u0442\u0430\u0440\u0434\u044B \u0456\u0437\u0434\u0435\u0443",
  "Search reciters": "\u049A\u0430\u0440\u0438\u043B\u0430\u0440\u0434\u044B \u0456\u0437\u0434\u0435\u0443",
  "Search the Names": "\u0415\u0441\u0456\u043C\u0434\u0435\u0440\u0434\u0456 \u0456\u0437\u0434\u0435\u0443",
  "Search the Quran": "\u049A\u04B1\u0440\u0430\u043D\u043D\u0430\u043D \u0456\u0437\u0434\u0435\u0443",
  "Search the hadith": "\u0425\u0430\u0434\u0438\u0441\u0442\u0435\u043D \u0456\u0437\u0434\u0435\u0443",
  "Search the live public directory": "\u0422\u0456\u043A\u0435\u043B\u0435\u0439 \u0436\u0430\u043B\u043F\u044B\u0493\u0430 \u043E\u0440\u0442\u0430\u049B \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0442\u0430\u043D \u0456\u0437\u0434\u0435\u0443",
  "Search the vocabulary": "\u0421\u04E9\u0437\u0434\u0456\u043A\u0442\u0435\u043D \u0456\u0437\u0434\u0435\u0443",
  "Search this book": "\u041E\u0441\u044B \u043A\u0456\u0442\u0430\u043F\u0442\u0430\u043D \u0456\u0437\u0434\u0435\u0443",
  "Search this collection": "\u041E\u0441\u044B \u0436\u0438\u043D\u0430\u049B\u0442\u0430\u043D \u0456\u0437\u0434\u0435\u0443",
