  "Subtracted from the total above": "\u0416\u043E\u0493\u0430\u0440\u044B\u0434\u0430\u0493\u044B \u0436\u0430\u043B\u043F\u044B\u0434\u0430\u043D \u0430\u043B\u044B\u043D\u0434\u044B",
  "Suhoor": "\u0421\u04D9\u0440\u0435\u0441\u0456",
  "Suhoor and Iftar for every day of the month": "\u0410\u0439\u0434\u044B\u04A3 \u04D9\u0440 \u043A\u04AF\u043D\u0456\u043D\u0435 \u0441\u04D9\u0440\u0435\u0441\u0456 \u043C\u0435\u043D \u0430\u0443\u044B\u0437\u0430\u0448\u0430\u0440",
  "Suhoor and Iftar timetable, fasting record and guides": "\u0421\u04D9\u0440\u0435\u0441\u0456 \u043C\u0435\u043D \u0430\u0443\u044B\u0437\u0430\u0448\u0430\u0440 \u043A\u0435\u0441\u0442\u0435\u0441\u0456, \u043E\u0440\u0430\u0437\u0430 \u0435\u0441\u0435\u0431\u0456 \u0436\u04D9\u043D\u0435 \u043D\u04B1\u0441\u049B\u0430\u0443\u043B\u044B\u049B\u0442\u0430\u0440",
  "Suhoor in": "\u0421\u04D9\u0440\u0435\u0441\u0456\u0433\u0435",
  "Sunan": "\u0421\u0443\u043D\u0430\u043D",
  "Sunnah Prayers": "\u0421\u04AF\u043D\u043D\u0435\u0442 \u043D\u0430\u043C\u0430\u0437\u0434\u0430\u0440",
  "Sunnah prayers": "\u0421\u04AF\u043D\u043D\u0435\u0442 \u043D\u0430\u043C\u0430\u0437\u0434\u0430\u0440",
  "Sunrise": "\u041A\u04AF\u043D\u043D\u0456\u04A3 \u0448\u044B\u0493\u0443\u044B",
  "Supplication and nearness": "\u0414\u04B1\u0493\u0430 \u0436\u04D9\u043D\u0435 \u0436\u0430\u049B\u044B\u043D\u0434\u044B\u049B",
  "Support": "\u049A\u043E\u043B\u0434\u0430\u0443",
