  "Switch to English": "\u0410\u0493\u044B\u043B\u0448\u044B\u043D\u0448\u0430\u0493\u0430 \u0430\u0443\u044B\u0441\u0442\u044B\u0440\u0443",
  "System": "\u0416\u04AF\u0439\u0435",
